package com.mavric.health.portal;
import java.util.*;
import java.time.Instant;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.*;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.*;
import com.mavric.health.scheduling.application.SchedulingService;
import com.mavric.health.scheduling.domain.Requests.Reserve;
import com.mavric.health.persistence.sqlserver.*;
import com.mavric.health.persistence.sqlserver.SqlServerPortalPatientsStoreTest.Fixture;
import static com.mavric.health.persistence.sqlserver.SqlServerPortalPatientsStoreTest.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Patients real service/store; offline executor and modeled TX. Other methods retain legacy collaborators. */
class PortalServicePatientsSqlServerTest {
 final Fixture f=new Fixture();final Sql sql=mock(Sql.class);final Access access=mock(Access.class);final SchedulingService scheduling=mock(SchedulingService.class);final SqlServerPortalDocumentStore documents=mock(SqlServerPortalDocumentStore.class);final SqlServerPortalAppointmentStore appointments=mock(SqlServerPortalAppointmentStore.class);final PortalService service=new PortalService(documents,appointments,f.store,sql,access,scheduling);
 PortalServicePatientsSqlServerTest(){actor("PAC");when(access.tenantId()).thenReturn(TENANT);when(access.userId()).thenReturn(ACTOR);}
 void actor(String role){f.actor(role);doReturn(f.actor).when(access).actor();TraceContext.REQUEST.set(f.request);}
 @AfterEach void clean(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 @Test void pacAndResPortalGateThenSingleSpNoAccessLinkOrLegacySql(){f.rows.add(row());for(String role:List.of("PAC","RES")){actor(role);var result=(List<?>)service.patients();assertEquals(1,result.size());assertEquals(7,((Map<?,?>)result.getFirst()).size());}verify(access,times(2)).roles("PAC","RES");verify(access,times(2)).module("PORTAL");verify(access,never()).link(anyString(),anyString());verify(access,never()).branch(anyString());verify(f.executor,times(2)).execute(eq(SqlServerProcedure.PORTAL_PATIENTS),any());verifyNoInteractions(sql,scheduling);}
 @Test void portalRoleOrModuleGatePreservesLegacyOrderAndStopsBeforeStore(){doThrow(new ApiException(401,"UNAUTHENTICATED","Safe")).when(access).roles("PAC","RES");assertEquals(401,assertThrows(ApiException.class,()->service.patients()).status);verify(access,never()).module(anyString());doNothing().when(access).roles("PAC","RES");doThrow(new ApiException(403,"MODULE_NOT_INCLUDED","Safe")).when(access).module("PORTAL");assertEquals("MODULE_NOT_INCLUDED",assertThrows(ApiException.class,()->service.patients()).code);verify(access,never()).actor();verifyNoInteractions(f.executor,sql,scheduling);}
 @Test void patientsHasNoClientArgumentsAndIgnoresForgedAuthorityHeaders(){f.request.addHeader("X-User-Id",OTHER);f.request.addHeader("X-Tenant-Id",OTHER);assertEquals(List.of(),service.patients());assertEquals(List.of(),f.args.getFirst());assertEquals(ACTOR,f.contexts.getFirst().actorId());assertEquals(TENANT,f.contexts.getFirst().tenantId());verify(access,never()).link(anyString(),anyString());verifyNoInteractions(sql,scheduling,documents,appointments);}
 @Test void missingRequest401ActorMismatchMalformedOrForeignHostFailBeforeSp(){TraceContext.REQUEST.remove();assertEquals(500,assertThrows(ApiException.class,()->service.patients()).status);actor("PAC");doThrow(new ApiException(401,"UNAUTHENTICATED","Safe")).when(access).actor();assertEquals(401,assertThrows(ApiException.class,()->service.patients()).status);actor("PAC");f.request.removeAttribute("health.actor");f.request.addHeader("X-Roles","PAC");assertEquals(403,assertThrows(ApiException.class,()->service.patients()).status);actor("PAC");f.request.setAttribute("health.tenant","bad");assertEquals(500,assertThrows(ApiException.class,()->service.patients()).status);actor("PAC");f.request.setAttribute("health.tenant",new TenantRef(OTHER,"Foreign","foreign","CLINIC","HUMAN","ACTIVE",List.of("PORTAL")));assertEquals(403,assertThrows(ApiException.class,()->service.patients()).status);verifyNoInteractions(f.executor,sql,scheduling);}
 @Test void forgedRolesAndPlatformNeverGrantedEvenWhenAccessIsDouble(){for(String role:List.of("ADM","REC","PRO","ASI","AUD","SAD","SOP")){actor(role);assertEquals(403,assertThrows(ApiException.class,()->service.patients()).status);}var platform=new Actor(ACTOR,"Synthetic","synthetic@example.test",null,List.of("SAD"),"a".repeat(64));doReturn(platform).when(access).actor();f.request.setAttribute("health.actor",platform);f.request.removeAttribute("health.tenant");assertEquals(403,assertThrows(ApiException.class,()->service.patients()).status);verifyNoInteractions(f.executor,sql,scheduling);}
 @Test void spLinkAndPermissionFailuresPropagateWithoutFallbackOrAccessLink(){for(int vendor:List.of(51001,51002)){doThrow(new RuntimeException(new java.sql.SQLException("private driver canary",null,vendor))).when(f.executor).execute(any(),any(),any(Object[].class));var error=assertThrows(ApiException.class,()->service.patients());assertEquals(vendor==51001?403:404,error.status);assertNull(error.getCause());assertFalse(error.toString().contains("canary"));}verify(f.executor,times(2)).execute(eq(SqlServerProcedure.PORTAL_PATIENTS),any());verify(access,never()).link(anyString(),anyString());verifyNoInteractions(sql,scheduling);}
 @Test void emptyImmutableAndPrivateColumnsNeverChangePublicShape(){assertEquals(List.of(),service.patients());var row=row();row.put("passwordHash","private-canary");row.put("tenantId",OTHER);row.put("published",false);row.put("withdrawn",true);f.rows.add(row);var result=(List<Map<String,Object>>)service.patients();assertEquals(7,result.getFirst().size());assertFalse(result.toString().contains("private-canary"));assertFalse(result.getFirst().containsKey("published"));assertThrows(UnsupportedOperationException.class,result::clear);assertThrows(UnsupportedOperationException.class,result.getFirst()::clear);verifyNoInteractions(sql,scheduling);}
 @Test void modeledCommitAndOuterCancellationNeverUseLegacyFallback(){f.manager.failCommit=true;var e=assertThrows(ApiException.class,()->service.patients());assertEquals(500,e.status);assertNull(e.getCause());assertThrows(RuntimeException.class,()->f.manager.outer(()->{service.patients();throw new RuntimeException("cancel");}));assertEquals("rollback",f.manager.events.getLast());assertSame(f.actor,f.request.getAttribute("health.actor"));verifyNoInteractions(sql,scheduling);}
 @Test void sixArgumentSelectionKeepsDocumentAppointmentAndOtherCollaborators(){when(sql.one(anyString(),any(Object[].class))).thenReturn(Map.of("balanceMinor",0,"currency","PEN"));var p=new Reserve(PATIENT,OTHER,OTHER,"H_FAMILY",Instant.parse(DATE),Instant.parse(DATE).plusSeconds(1800),"REQUESTED","Synthetic","");when(scheduling.reserve(p,"synthetic-key-001",true)).thenReturn(Map.of("id",PATIENT));var expected=List.<Map<String,Object>>of(Map.of("id",OTHER));when(documents.documents(f.request,PATIENT)).thenReturn(expected);when(appointments.appointments(f.request,PATIENT)).thenReturn(expected);assertSame(expected,service.documents(PATIENT));assertSame(expected,service.appointments(PATIENT));assertEquals(Map.of("balanceMinor",0,"currency","PEN"),service.balance(PATIENT));assertEquals(Map.of("id",PATIENT),service.reserve(p,"synthetic-key-001"));verify(documents).documents(f.request,PATIENT);verify(appointments).appointments(f.request,PATIENT);verify(access).link(PATIENT,"BILLING");verify(access,never()).link(PATIENT,"DOCUMENTS");verify(access,never()).link(PATIENT,"APPOINTMENTS");verify(access).module("FINANCE");verify(sql).one(anyString(),any(Object[].class));verifyNoInteractions(f.executor);}
 @Test void existingA40AndA41ConstructorsKeepPatientsLegacyAndMigratedStoresUntouched(){when(sql.rows(anyString(),any(Object[].class))).thenReturn(List.of());var a40=new PortalService(documents,sql,access,scheduling);var a41=new PortalService(documents,appointments,sql,access,scheduling);assertEquals(List.of(),a40.patients());assertEquals(List.of(),a41.patients());verify(sql,times(2)).rows(anyString(),eq(TENANT),eq(ACTOR));verifyNoInteractions(documents,appointments,f.executor);}
 @Test void minimalSpringSelectsLegacyConstructorAndKeepsLegacyPatientsQuery(){when(sql.rows(anyString(),any(Object[].class))).thenReturn(List.of(row()));try(var context=new AnnotationConfigApplicationContext()){context.registerBean(Sql.class,()->sql);context.registerBean(Access.class,()->access);context.registerBean(SchedulingService.class,()->scheduling);context.registerBean(PortalService.class);context.refresh();var legacy=context.getBean(PortalService.class);assertEquals(1,((List<?>)legacy.patients()).size());verify(sql).rows(anyString(),eq(TENANT),eq(ACTOR));assertEquals(0,context.getBeanNamesForType(SqlServerPortalPatientsStore.class).length);assertEquals(0,context.getBeanNamesForType(javax.sql.DataSource.class).length);}verify(access,never()).link(anyString(),anyString());verifyNoInteractions(f.executor,scheduling,documents,appointments);}
}
